  tablo: 'takipler' | 'sohbet_istekleri',
  sutun: string,
  kosulSutunu: string,
  kosulDegeri: string,
  durum: 'beklemede' | 'kabul'
): Promise<string[]> {
  const { data, error } = await supabase
    .from(tablo)
    .select(sutun)
    .eq(kosulSutunu, kosulDegeri)
